sys_script_include.script:
var FeedbackUtils = Class.create();
FeedbackUtils.prototype = {
    initialize: function () {
        this._feedbackTable = 'x_1610434_event_0_feedback';
    },

    getFeedbackDetailsById: function (_feedbackId) {
        var _feedbackGR = new GlideRecordSecure(this._feedbackTable);
        _feedbackGR.addQuery('sys_id', _feedbackId);
        _feedbackGR.query();
        if (_feedbackGR.next()) {
            return this._mapFeedback(_feedbackGR);
        }
        return null;
    },

    isFeedbackPositive: function (_feedbackId) {
        var _feedbackGR = new GlideRecordSecure(this._feedbackTable);
        _feedbackGR.addQuery('sys_id', _feedbackId);
        _feedbackGR.query();
        if (_feedbackGR.next()) {
            var _rating = _feedbackGR.getValue('rating');
            return _rating == 'excellent' || _rating == 'good';
        }
        return false;
    },

    getFeedbackByEvent: function (_eventId) {
        var _feedbackList = [];
        var _feedbackGR = new GlideRecordSecure(this._feedbackTable);
        _feedbackGR.addQuery('event_id', _eventId);
        _feedbackGR.query();
        while (_feedbackGR.next()) {
            _feedbackList.push(this._mapFeedback(_feedbackGR));
        }
        return _feedbackList;
    },

	_mapFeedback: function(_feedbackGR) {
        return {
            sysId: _feedbackGR.getUniqueValue(),
			feedbackId: _feedbackGR.getValue('number'),
            eventId: _feedbackGR.getValue('event_id'),
            attendeeId: _feedbackGR.getValue('attendee_id'),
            rating: _feedbackGR.getValue('rating'),
            comment: _feedbackGR.getValue('comment')
        };
    },

    type: 'FeedbackUtils'
};
